class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.7.0/commando_0.7.0_darwin_arm64.tar.gz"
      sha256 "edcf408bc5e82bdcd5dccbf4729eb0992b0e20397acb9f67df2e51591a98075a"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.7.0/commando_0.7.0_darwin_amd64.tar.gz"
      sha256 "8b893c6160ab9c50b22d05ff529e235c440ad986e85174ac29ee29ec78371ce7"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.7.0/commando_0.7.0_linux_arm64.tar.gz"
      sha256 "26c3a36757860963d8b5c652d908931ac619346cff9486557a0a733d6d01f105"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.7.0/commando_0.7.0_linux_amd64.tar.gz"
      sha256 "f112896188b8e678d8fe6483cd2d3ed813499e7d09f0fa4f60d41a91a1c75168"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
